"""從 PCCES 資料庫組出跟 XML 同一個 Budget／PayItem，讓排版與 check_consistency 共用。

欄位對應見 docs\\資料表與XML對照.md 第 2.1、2.3、2.4 節；兩個示範案例逐筆比過。
讀取工具帶 item 看單價分析組成、查資源統計時，另用 `read_document` 組出詳細表＋單價分析＋資源統計的
`ETenderDocument`（對照文件 2.2、2.3），跟 XML 那一路共用 `xml.item_view`、`xml.resources`。
"""

from __future__ import annotations

from contextlib import closing
from dataclasses import dataclass
from decimal import Decimal
from typing import Any

from ..xml.document import ETenderDocument, Item, ItemList, Node
from ..xml.etender import Budget, PayItem
from ..xml.resources import expand
from .connection import connect, select

# 列表與找不到工程時列可選代碼共用
LIST_SQL = """
SELECT RTRIM(B.projectCode) AS code, B.projectNameC AS name, B.projamt,
       (SELECT COUNT(*) FROM budItemA A WHERE A.projectCode = B.projectCode) AS n_items
FROM budProject B
ORDER BY B.projectCode
"""

HEAD_SQL = """
SELECT RTRIM(B.projectCode) AS code, B.projectNameC AS title, B.mainCName AS entity,
       B.projectAddress AS location, B.projamt, D.itemQty, D.itemCost, D.itemAmt
FROM budProject B
LEFT JOIN pubDecimal D ON D.projectCode = B.projectCode
WHERE B.projectCode = ?
"""

# 詳細表一列＝budItemA 一列。平面撈出本案全部列，樹與順序在 Python 建（detail_rows）、itemKind 也在 Python 對（item_kind），
# 不連資料庫就測得到。v0.5.1 用遞迴 CTE 在 SQL 裡長樹，實案（3721 列）一次要 14～18 秒。
ITEMS_SQL = """
SELECT A.sNo                                   AS itemKey,      -- PayItem/@itemKey
       RTRIM(A.itemNo)                         AS itemNo,       -- PayItem/@itemNo
       RTRIM(ISNULL(A.kind, ''))               AS kind,         -- PayItem/@itemKind 見 item_kind
       RTRIM(ISNULL(M.analysis, ''))           AS analysis,
       RTRIM(ISNULL(M.costKind, ''))           AS costKind,
       RTRIM(ISNULL(A.PccesCode, ''))          AS refItemCode,  -- PayItem/@refItemCode
       RTRIM(A.cName)                          AS description,  -- Description[zh-TW]
       RTRIM(ISNULL(A.unitName, ''))           AS unit,         -- Unit[zh-TW]
       A.qty, A.cost AS price, A.amount,                        -- Quantity / Price / Amount
       ISNULL(RTRIM(A.memo), '')
         + CASE WHEN PB.IsBid = 'Y' THEN N'[發包]' ELSE N'' END
         + CASE WHEN A.PrintToAnalysis = '1' THEN N'[印單]' ELSE N'' END AS remark,  -- Remark
       A.rate AS percent_,                                      -- Percent
       A.ParentSno, A.SortOrder, RTRIM(A.printNo) AS printNo,
       A.pubCode                                                -- 工項連到 budProjMrsA（單價分析）
FROM budItemA A
LEFT JOIN BudPageBreak PB ON PB.ProjectCode = A.projectCode AND PB.SNo = A.sNo
LEFT JOIN budProjMrsA M ON M.projectCode = A.projectCode AND M.pubCode = A.pubCode AND A.pubCode <> 0
WHERE A.projectCode = ?
"""

# 小計列的自訂公式＝XML 小計列的 mml:math（實案 161 列引用 2、128，VarSign 1）
REFS_SQL = """
SELECT B.parentCodeSno, B.itemCodeSno, B.VarSign
FROM budItemB B
JOIN budItemA A ON A.projectCode = B.projectCode AND A.sNo = B.parentCodeSno
WHERE B.projectCode = ? AND A.kind = 'Z'
ORDER BY B.parentCodeSno, B.itemCode
"""

# ResourceList 的 PayItem 段＝詳細表裡這幾類（U 只在預存程序出現，兩案都沒有）
RESOURCE_KINDS = ("L", "S", "F", "U")

# 單價分析（對照文件 2.2）：本案工料主檔與分析組成；組成的單價取 MrsB.cost，不是 MrsA.cost（% 類兩者不同）
MRS_A_SQL = """
SELECT pubCode, RTRIM(ISNULL(pccesCode, '')) AS code, cName, RTRIM(ISNULL(unitName, '')) AS unit,
       RTRIM(ISNULL(costKind, '')) AS costKind, RTRIM(ISNULL(analysis, '')) AS analysis, analysisQty, cost, rate,
       RTRIM(ISNULL(LockCost, '')) AS LockCost
FROM budProjMrsA
WHERE projectCode = ?
"""

MRS_B_SQL = """
SELECT parentCode, pubCode, listNo, qty, cost, amount, RTRIM(ISNULL(LockCost, '')) AS LockCost
FROM budProjMrsB
WHERE projectCode = ?
ORDER BY parentCode, listNo
"""

# CostBreakdownList 三個位數（對照文件 2.4 最後一列）
ANALYSIS_DEC_SQL = """
SELECT analysisQty, analysisCost, analysisAmt
FROM pubDecimal
WHERE projectCode = ?
"""

# 組成的 itemKind（對照文件 2.2）：子項本身是分析就是巢狀分析
_COST_KIND = {"": "general", "%": "variableSumPercentage", "$": "variablePrice"}
# 資源統計 WorkItem 的 itemKind（對照文件 2.3）：costKind `#` 在這裡是 formula（詳細表那邊是 general）
_RES_KIND = {**_COST_KIND, "#": "formula"}


class ProjectNotFound(LookupError):
    def __init__(self, code: str, available: list[str]):
        self.code = code
        self.available = available
        shown = "、".join(available[:30]) + ("…" if len(available) > 30 else "")
        super().__init__(f"PCCES 資料庫裡沒有工程代碼「{code}」，目前有：{shown or '（一份都沒有）'}。")


@dataclass
class BudgetSummary:
    code: str
    name: str
    total: Decimal | None
    n_items: int


def _s(v: Any) -> str:
    # 跟 XML 解析器一樣 strip，兩邊的字串才比得起來
    return (v or "").strip()


def _dec(v: Any) -> Decimal | None:
    """資料庫 decimal(20,4) 帶尾端 0、比例是 float；整理成跟 XML 文字一樣的寫法，排版才一致。"""
    if v is None:
        return None
    d = v if isinstance(v, Decimal) else Decimal(str(v))
    return d.quantize(Decimal(1)) if d == d.to_integral_value() else d.normalize()


def _summaries(conn) -> list[BudgetSummary]:
    return [
        BudgetSummary(code=_s(r["code"]), name=_s(r["name"]), total=_dec(r["projamt"]), n_items=r["n_items"])
        for r in select(conn, LIST_SQL)
    ]


def list_budgets() -> list[BudgetSummary]:
    with closing(connect()) as conn:
        return _summaries(conn)


def _pay_item(r: dict[str, Any], *, resource: bool = False) -> PayItem:
    return PayItem(
        # 資源統計的 PayItem 段 itemKey 放的是項次、沒有 itemNo 與 itemKind（對照文件 2.3）
        item_key=_s(r["itemNo"]) if resource else str(r["itemKey"]),
        item_no="" if resource else _s(r["itemNo"]),
        kind="" if resource else _s(r["itemKind"]),
        description=_s(r["description"]),
        unit=_s(r["unit"]),
        quantity=_dec(r["qty"]),
        price=_dec(r["price"]),
        amount=_dec(r["amount"]),
        remark=_s(r["remark"]),
        percent=_dec(r["percent_"]),
        ref_item_code="" if resource else _s(r["refItemCode"]),
    )


def _head(conn, code: str) -> dict[str, Any]:
    head = select(conn, HEAD_SQL, code.strip())
    if not head:
        raise ProjectNotFound(code.strip(), [s.code for s in _summaries(conn)])
    return head[0]


# budItemA.kind → itemKind（對照文件 2.1）；W 另看工項連到的 budProjMrsA，見 item_kind
_DETAIL_KIND = {"Z": "subtotal", "B": "mainItem", "F": "formula", "S": "formula", "L": "general"}


def item_kind(kind: Any, analysis: Any, cost_kind: Any) -> str:
    """詳細表一列的 itemKind。W（工項）：MrsA.analysis='1' 是 analysis；沒有分析、MrsA.costKind 是 `$` 是
    variablePrice（實案 1103 列，XML 也是）；其餘是 general（含 costKind `#` 的 105 列，XML 也是 general）。"""
    k = _s(kind)
    if k == "W":
        if _s(analysis) == "1":
            return "analysis"
        return "variablePrice" if _s(cost_kind) == "$" else "general"
    return _DETAIL_KIND.get(k, "?" + k)


def _grand_total_last(r: dict[str, Any]) -> bool:
    # 總計列 kind='Z'（sNo 999999、printNo 全 9）掛在頂層、SortOrder=0，XML 把它放最後。
    # 只有這一列往後排：中間的小計列（實案 217 列）照 SortOrder 留在原位，小計規則看的是同層前後順序（PCX-003）。
    return _s(r["kind"]) == "Z" and r["ParentSno"] == 0 and r["SortOrder"] == 0


def detail_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """ITEMS_SQL 撈出的列補上 itemKind，排成 XML 詳細表的先序：ParentSno 長樹、同層依 SortOrder。

    跟 v0.5.1 的遞迴 CTE 同一套順序（五份示範工程與實案輸出逐行相同）。接不上頂層的列
    （ParentSno 指到不存在的項）不在回傳裡，呼叫端拿筆數差講明。同層 SortOrder 重複時再依 sNo，
    只為了每次結果一樣（現有資料沒有重複）。
    """
    kids: dict[Any, list[dict[str, Any]]] = {}
    for r in rows:
        r["itemKind"] = item_kind(r["kind"], r["analysis"], r["costKind"])
        kids.setdefault(r["ParentSno"], []).append(r)
    for sibs in kids.values():
        sibs.sort(key=lambda r: (_grand_total_last(r), r["SortOrder"], r["itemKey"]))
    out: list[dict[str, Any]] = []
    seen: set = set()
    stack = list(reversed(kids.get(0, [])))
    while stack:
        r = stack.pop()
        if r["itemKey"] in seen:  # sNo＝0 這種會繞回頂層的資料，不重複走
            continue
        seen.add(r["itemKey"])
        out.append(r)
        stack.extend(reversed(kids.get(r["itemKey"], [])))
    return out


def _unlinked(raw: list, rows: list) -> list[str]:
    n = len(raw) - len(rows)
    return [f"資料庫有 {n} 列詳細表沒接上項目樹（ParentSno 指到不存在的項），沒列進來也沒算進檢查"] if n else []


def read_budget(code: str) -> tuple[Budget, list[str]]:
    """回傳（預算書, 警告）。警告是資料庫裡有、但沒接上項目樹的列，排版時要讓使用者看到。"""
    with closing(connect()) as conn:
        h = _head(conn, code)
        raw = select(conn, ITEMS_SQL, h["code"])
        refs = select(conn, REFS_SQL, h["code"])
    return budget_from_rows(h, raw, refs)


def budget_from_rows(h: dict[str, Any], raw: list[dict[str, Any]], refs: list[dict[str, Any]]) -> tuple[Budget, list[str]]:
    """HEAD_SQL 一列、ITEMS_SQL 全部列（順序不拘）、REFS_SQL 組出 `Budget`；不碰資料庫，測試拿合成的列直接餵。"""
    rows = detail_rows(raw)
    # 先建全部節點再掛父子；rows 已是先序，掛上去的順序就是同層順序
    nodes = {r["itemKey"]: _pay_item(r) for r in rows}
    top: list[PayItem] = []
    for r in rows:
        parent = r["ParentSno"]
        (top if parent == 0 else nodes[parent].children).append(nodes[r["itemKey"]])
    for r in refs:
        it = nodes.get(r["parentCodeSno"])
        if it is None or it.sum_refs_error:
            continue
        if r["itemCodeSno"] is None or r["VarSign"] is None:
            # 自訂變數或沒有正負號：XML 那一路也看不懂，同樣講明沒核對
            it.sum_refs, it.sum_refs_error = None, "引用自訂變數或沒有正負號"
            continue
        it.sum_refs = (it.sum_refs or []) + [(int(r["VarSign"]), str(r["itemCodeSno"]))]

    resources = [_pay_item(r, resource=True)
                 # 資源統計 PayItem 依 (kind, printNo) 排：F 排在 L 前面；只依 printNo 時實案 5 列只對 1 列（示範案例兩種排法相同）
                 for r in sorted((r for r in rows if r["kind"] in RESOURCE_KINDS), key=lambda r: (r["kind"], r["printNo"]))]
    budget = Budget(
        contract_no=_s(h["code"]),
        title=_s(h["title"]),
        procuring_entity=_s(h["entity"]),
        location=_s(h["location"]),
        items=top,
        resource_items=resources,
        total_amount=_dec(h["projamt"]),
        price_decimals=int(h["itemCost"] or 0),
        amount_decimals=int(h["itemAmt"] or 0),
    )
    return budget, _unlinked(raw, rows)


# ---------- 單價分析（讀取工具帶 item 用） ----------


def _txt(v: Any) -> str:
    """跟 XML 文字同一種寫法（1000、683.78、3），item_view 比對與排版才跟 XML 那一路一致。"""
    d = _dec(v)
    return "" if d is None else format(d, "f")


def _f(tag: str, text: str, **attrs: str) -> Node:
    return Node(tag, dict(attrs), text)


def _detail_item(r: dict[str, Any]) -> Item:
    return Item("PayItem", {
        "itemKey": str(r["itemKey"]), "itemNo": _s(r["itemNo"]),
        "refItemCode": _s(r["refItemCode"]), "itemKind": _s(r["itemKind"]),
    }, [
        _f("Description", _s(r["description"]), language="zh-TW"),
        _f("Unit", _s(r["unit"]), language="zh-TW"),
        _f("Quantity", _txt(r["qty"])), _f("Price", _txt(r["price"])), _f("Amount", _txt(r["amount"])),
        _f("Remark", _s(r["remark"])), _f("Percent", _txt(r["percent_"])),
    ])


def _components(pub: int, mrs_a: dict[int, dict], mrs_b: dict[int, list[dict]], stack: tuple = ()) -> list[Item]:
    """一個分析的組成列（budProjMrsB 依 listNo）；組成本身是分析時往下接它的組成，跟 XML 的巢狀分析一樣。"""
    out: list[Item] = []
    for b in mrs_b.get(pub, []):
        a = mrs_a.get(b["pubCode"], {})
        nested = _s(a.get("analysis")) == "1"
        kind = "analysis" if nested else _COST_KIND.get(_s(a.get("costKind")), "?" + _s(a.get("costKind")))
        it = Item("WorkItem", {
            "itemCode": _s(a.get("code")) or f"pubCode {b['pubCode']}", "itemKind": kind,
            "analysisOutputQuantity": _txt(a.get("analysisQty")) or "1",
        }, [
            _f("Description", _s(a.get("cName")), language="zh-TW"),
            _f("Unit", _s(a.get("unit")), language="zh-TW"),
            _f("Quantity", _txt(b["qty"])),
            _f("Price", _txt(b["cost"]), fixed="true" if _s(b["LockCost"]) == "1" else "false"),
            _f("Amount", _txt(b["amount"]), fixed="false"),
            _f("Percent", _txt(a.get("rate"))),
        ])
        if nested and b["pubCode"] not in stack:
            it.children = _components(b["pubCode"], mrs_a, mrs_b, stack + (pub,))
        out.append(it)
    return out


def read_document(code: str) -> ETenderDocument:
    """詳細表＋單價分析組成＋資源統計的 `ETenderDocument`，給 `xml.item_view`、`xml.resources` 用；
    只有這三段與表頭的查詢用欄位，不能拿去寫出 XML。

    單價分析表頂層＝詳細表裡每一列有單價分析的工項，照詳細表順序（同一分析被兩列用到就兩份，跟 XML 一樣）。
    資源統計見 `_resource_list`。
    """
    with closing(connect()) as conn:
        h = _head(conn, code)
        raw = select(conn, ITEMS_SQL, h["code"])
        mrs_a = select(conn, MRS_A_SQL, h["code"])
        mrs_b = select(conn, MRS_B_SQL, h["code"])
        dec = select(conn, ANALYSIS_DEC_SQL, h["code"])
    return document_from_rows(h, raw, mrs_a, mrs_b, dec)


def document_from_rows(h: dict[str, Any], raw: list[dict[str, Any]], mrs_a_rows: list[dict[str, Any]],
                       mrs_b_rows: list[dict[str, Any]], dec: list[dict[str, Any]]) -> ETenderDocument:
    """`read_document` 不碰資料庫的那一半：五句 SELECT 的結果組成 `ETenderDocument`，測試拿合成的列直接餵。"""
    rows = detail_rows(raw)
    mrs_a = {r["pubCode"]: r for r in mrs_a_rows}
    mrs_b: dict[int, list[dict]] = {}
    for r in mrs_b_rows:  # MRS_B_SQL 已依 parentCode、listNo 排好
        mrs_b.setdefault(r["parentCode"], []).append(r)

    nodes = {r["itemKey"]: _detail_item(r) for r in rows}
    top: list[Item] = []
    for r in rows:
        (top if r["ParentSno"] == 0 else nodes[r["ParentSno"]].children).append(nodes[r["itemKey"]])
    cbl: list[Item] = []
    for r in rows:
        a = mrs_a.get(r["pubCode"])
        if _s(r["itemKind"]) != "analysis" or a is None or nodes[r["itemKey"]].children:
            continue
        w = Item("WorkItem", {
            "itemCode": _s(a["code"]), "refItemNo": _s(r["itemNo"]), "itemKind": "analysis",
            "analysisOutputQuantity": _txt(a["analysisQty"]) or "1",
        }, [
            _f("Description", _s(r["description"]), language="zh-TW"),
            _f("Unit", _s(a["unit"]), language="zh-TW"),
            _f("Quantity", _txt(a["analysisQty"])), _f("Price", _txt(a["cost"])),
        ])
        w.children = _components(r["pubCode"], mrs_a, mrs_b)
        cbl.append(w)
    d = dec[0] if dec else {"analysisQty": 0, "analysisCost": 0, "analysisAmt": 0}

    def digits(q, p, a) -> dict[str, str]:
        return {"quantityDisplayDecimal": str(int(q or 0)), "unitPriceDisplayDecimal": str(int(p or 0)),
                "itemAmountDisplayDecimal": str(int(a or 0))}

    doc = ETenderDocument(
        root_attrs={},
        tender_information=Node("TenderInformation", {"contractNo": _s(h["code"])},
                                children=[_f("ContractTitle", _s(h["title"]), language="zh-TW")]),
        detail_list=ItemList("DetailList", digits(h["itemQty"], h["itemCost"], h["itemAmt"]), top),
        cost_breakdown_list=ItemList("CostBreakdownList", digits(d["analysisQty"], d["analysisCost"], d["analysisAmt"]), cbl),
        resource_list=None,
        grand_total=Node("GrandTotalInformation", children=[_f("TotalAmount", _txt(h["projamt"]))]),
    )
    # 資源統計的位數跟詳細表同一組（實案 XML 是 3/0/0，單價分析表是 3/2/2）
    doc.resource_list = _resource_list(doc, rows, mrs_a_rows, mrs_b,
                                       digits(h["itemQty"], h["itemCost"], h["itemAmt"]))
    return doc


def _resource_list(doc: ETenderDocument, rows: list[dict[str, Any]], mrs_a_rows: list[dict[str, Any]],
                   mrs_b: dict[int, list[dict]], attrs: dict[str, str]) -> ItemList:
    """資源統計（對照文件 2.3）。數量、複價用 `xml.resources.expand` 從上面組好的詳細表＋單價分析展開，
    跟 XML 那一路同一支：數量＝Σ round(用量, 4)＋直接列的數量，複價＝Σ round(用量 × MrsB.cost, 4)＋直接列的複價。

    複價是 PCCES 4.3 重新總計的算法（重新總計後 usrAmt 就等於它），不取 usrAmt 快取：沒重新總計的工程
    快取會整批是 NULL（實案 271 筆）。所以拿沒重新總計就匯出的舊檔（ArchEx001 示範檔）來比，複價只對得上一部分。
    """
    exp = expand(doc)
    has_kids = lambda a: _s(a["analysis"]) == "1" and bool(mrs_b.get(a["pubCode"]))  # noqa: E731
    # 集合：去掉有子項的分析項、代碼 # 開頭、costKind Z；costKind # 要列。順序 pubCode（本機工料庫的鍵）
    picked = sorted((a for a in mrs_a_rows
                     if not has_kids(a) and not _s(a["code"]).startswith("#") and _s(a["costKind"]) != "Z"),
                    key=lambda a: a["pubCode"])
    items: list[Item] = []
    seen: set[str] = set()
    for a in picked:
        code, ck = _s(a["code"]), _s(a["costKind"])
        if code in seen:  # 一碼一筆（三案都沒有重複代碼）
            continue
        seen.add(code)
        fields = [_f("Description", _s(a["cName"]), language="zh-TW"), _f("Unit", _s(a["unit"]), language="zh-TW"),
                  _f("Quantity", _txt(exp.quantity(code)))]
        if ck == "":  # % 類、變動單價、# 不輸出 Price（連 @fixed 也沒有）
            fields.append(_f("Price", _txt(a["cost"]), fixed="true" if _s(a["LockCost"]) == "1" else "false"))
        fields += [_f("Amount", _txt(exp.amount(code)), fixed="false"), _f("Percent", _txt(a["rate"]))]
        items.append(Item("WorkItem", {"itemCode": code, "itemKind": _RES_KIND.get(ck, "?" + ck)}, fields))
    # PayItem 段：詳細表 kind L／S／F／U，依 (kind, printNo)，itemKey 放項次（跟 budget_from_rows 同一條）
    for r in sorted((r for r in rows if r["kind"] in RESOURCE_KINDS), key=lambda r: (r["kind"], r["printNo"])):
        items.append(Item("PayItem", {"itemKey": _s(r["itemNo"])}, [
            _f("Description", _s(r["description"]), language="zh-TW"), _f("Unit", _s(r["unit"]), language="zh-TW"),
            _f("Quantity", _txt(r["qty"])), _f("Price", _txt(r["price"])), _f("Amount", _txt(r["amount"])),
            _f("Remark", _s(r["remark"])), _f("Percent", _txt(r["percent_"])),
        ]))
    return ItemList("ResourceList", attrs, items)
